import{_ as a,c as i,a0 as l,o}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"v1.1.5 发布说明","description":"","frontmatter":{},"headers":[],"relativePath":"release/v1.1.5.md","filePath":"release/v1.1.5.md"}'),c={name:"release/v1.1.5.md"};function d(t,e,r,s,n,h){return o(),i("div",null,e[0]||(e[0]=[l('<h1 id="v1-1-5-发布说明" tabindex="-1">v1.1.5 发布说明 <a class="header-anchor" href="#v1-1-5-发布说明" aria-label="Permalink to &quot;v1.1.5 发布说明&quot;">​</a></h1><p>发布日期：2026-07-30 适用分支：<code>main</code> 基线：<code>v1.1.4</code>（<code>fa2fd0a</code>）</p><hr><h2 id="_1-发布目标" tabindex="-1">1. 发布目标 <a class="header-anchor" href="#_1-发布目标" aria-label="Permalink to &quot;1. 发布目标&quot;">​</a></h2><p>v1.1.5 是 API 边界与状态通道治理补丁，不改动播放协调器、设备播放器和运行时仲裁实现。</p><p>本版解决两类长期偏差：</p><ol><li>WebUI 管理与诊断能力占用 Runtime Public API 命名空间，公开 schema 与 25 项正式白名单不一致。</li><li>WebUI 会读取播放命令响应中的即时状态快照，与 SSE / <code>player/state</code> 权威状态通道形成并行来源。</li></ol><hr><h2 id="_2-主要变化" tabindex="-1">2. 主要变化 <a class="header-anchor" href="#_2-主要变化" aria-label="Permalink to &quot;2. 主要变化&quot;">​</a></h2><h3 id="_2-1-api-分层" tabindex="-1">2.1 API 分层 <a class="header-anchor" href="#_2-1-api-分层" aria-label="Permalink to &quot;2.1 API 分层&quot;">​</a></h3><ul><li>Runtime Public API：<code>/api/v1/*</code>，公开 OpenAPI 精确保留 25 项正式接口。</li><li>Admin API：新增 <code>/api/admin/v1/sources/*</code> 与 <code>/api/admin/v1/auth/status</code>。</li><li>Internal Diagnostics：新增 <code>/api/internal/diagnostics/*</code>，不进入公开 schema。</li><li>原 <code>/api/v1/sources/*</code>、<code>/api/v1/auth/status</code>、<code>/api/v1/debug/*</code> 保留兼容，隐藏并标记弃用。</li><li>新旧路径共享业务实现和唯一 <code>PlaybackFacade</code>。</li></ul><h3 id="_2-2-请求边界" tabindex="-1">2.2 请求边界 <a class="header-anchor" href="#_2-2-请求边界" aria-label="Permalink to &quot;2.2 请求边界&quot;">​</a></h3><ul><li><code>PlayRequest</code>、<code>ResolveRequest</code> 拒绝空白 query。</li><li><code>source_hint</code> 限制为正式枚举。</li><li>options 使用结构化模型并严格验证布尔字段。</li><li>未声明的顶层字段和 options 字段被拒绝。</li><li>v1 422 返回统一 envelope，并包含 <code>E_INVALID_REQUEST</code> 与 <code>stage=request</code>。</li></ul><h3 id="_2-3-webui-状态来源" tabindex="-1">2.3 WebUI 状态来源 <a class="header-anchor" href="#_2-3-webui-状态来源" aria-label="Permalink to &quot;2.3 WebUI 状态来源&quot;">​</a></h3><ul><li>Sources 页面切换到 Admin API。</li><li>首页不再读取 <code>POST /api/v1/play</code> 的 <code>data.state</code>。</li><li>播放器展示只由 SSE 或 <code>/api/v1/player/state</code> polling 更新。</li><li>过期或伪造的命令响应状态不会覆盖权威页面状态。</li></ul><hr><h2 id="_3-兼容性边界" tabindex="-1">3. 兼容性边界 <a class="header-anchor" href="#_3-兼容性边界" aria-label="Permalink to &quot;3. 兼容性边界&quot;">​</a></h2><ul><li>本版不删除旧 API 路径。</li><li>本版不删除 <code>/api/v1/play</code> 后端响应中的 <code>data.state</code>，仅停止 WebUI 消费。</li><li>本版不删除 <code>player/state</code> 的旧兼容字段。</li><li>后续移除需另行完成调用方调查并按破坏性变更处理。</li></ul><hr><h2 id="_4-发布门禁" tabindex="-1">4. 发布门禁 <a class="header-anchor" href="#_4-发布门禁" aria-label="Permalink to &quot;4. 发布门禁&quot;">​</a></h2><p>发布前必须完成：</p><ul><li>Python API 专项与相关回归通过。</li><li>WebUI Vitest 与 TypeScript 检查通过。</li><li>测试服务器完成完整源码包构建，不允许散件覆盖。</li><li>容器版本、健康、公开 OpenAPI、Admin API、WebUI 静态资源通过。</li><li>实机前设置测试设备音量为 0，并回读确认。</li><li>播放与状态流验收结束后执行 stop，再 probe 确认 <code>status=2</code>。</li><li>上述门禁全部通过后方可推送、打 <code>v1.1.5</code> 标签并创建 Release。</li></ul><hr><h2 id="_5-测试服务器验收结果" tabindex="-1">5. 测试服务器验收结果 <a class="header-anchor" href="#_5-测试服务器验收结果" aria-label="Permalink to &quot;5. 测试服务器验收结果&quot;">​</a></h2><p>测试环境：<code>192.168.7.178</code>，OH2P（Xiaomi 智能音箱 Pro）。</p><h3 id="_5-1-构建与接口" tabindex="-1">5.1 构建与接口 <a class="header-anchor" href="#_5-1-构建与接口" aria-label="Permalink to &quot;5.1 构建与接口&quot;">​</a></h3><ul><li>最终源码包 SHA256：<code>05822e0b417abd30ccb4a6350cd36e0cb81332311ebcc88ced8740b91e90c9fb</code></li><li>Docker 镜像：<code>sha256:2a1cb8e0a56305485ac2b5af0785e26072c684bcc15a2c8f81629a38edb82140</code></li><li><code>/getversion</code>：<code>1.1.5</code></li><li>WebUI 首页、JS、CSS：HTTP 200</li><li>Public v1：精确 25 项；Admin API：精确 7 项；Internal/compat 未泄漏到公开 schema</li><li>Admin Sources 新路径与旧兼容路径：均返回统一 envelope</li><li>空白 query、非法 source_hint、错误 shuffle 类型、未知字段：均返回 HTTP 422、<code>E_INVALID_REQUEST</code>、<code>stage=request</code></li></ul><h3 id="_5-2-实机与状态通道" tabindex="-1">5.2 实机与状态通道 <a class="header-anchor" href="#_5-2-实机与状态通道" aria-label="Permalink to &quot;5.2 实机与状态通道&quot;">​</a></h3><ul><li>OH2P 对 volume 0 的物理回读为最低值 4；经用户明确允许后，以最低物理音量 4 使用 8 秒静音媒体完成测试。</li><li><code>POST /api/v1/play</code>：<code>code=0</code>，响应 7 ms，transport=<code>mina</code></li><li>音箱请求媒体：HTTP 206</li><li><code>/api/v1/player/state</code>：观察到 <code>transport_state=playing</code>、track=<code>v115_accept</code></li><li>SSE：收到对应 <code>player_state</code> 权威快照，duration=<code>8000ms</code></li><li>Raw device：播放中 <code>status=1</code>、volume=4</li><li>stop 后权威状态：<code>stopped</code></li><li>最终 probe：<code>status=2</code>、volume=4</li><li>10 秒无复播；再次 probe 仍为 <code>status=2</code></li><li>临时测试媒体已删除，媒体库已刷新</li></ul><h3 id="_5-3-本地门禁" tabindex="-1">5.3 本地门禁 <a class="header-anchor" href="#_5-3-本地门禁" aria-label="Permalink to &quot;5.3 本地门禁&quot;">​</a></h3><ul><li>Python API 与相关回归：90 passed</li><li>WebUI：11 files / 48 tests passed</li><li>TypeScript build：passed</li><li>Ruff：passed</li><li><code>git diff --check</code>：passed</li></ul><hr><h2 id="_6-回滚原则" tabindex="-1">6. 回滚原则 <a class="header-anchor" href="#_6-回滚原则" aria-label="Permalink to &quot;6. 回滚原则&quot;">​</a></h2><ul><li>测试服务器部署前保留当前镜像不可覆盖标签和完整源码快照。</li><li>候选在独立目录构建，保留原配置、音乐目录与认证数据。</li><li>任一门禁失败时停止发布，恢复旧容器与镜像，并重新确认设备停止状态。</li></ul>',34)]))}const b=a(c,[["render",d]]);export{p as __pageData,b as default};
